window.ALBORZ_SPRINT_QA_PART_A={"1":[{"q":"مهمان ناراضی فقط ۲۰ دقیقه وقت دارد. گفت‌وگو را چطور شروع می‌کنید؟","options":["خوشامد می‌گویم و بلافاصله می‌روم سراغ بررسی پرونده.","وقت محدودش را می‌پذیرم و می‌پرسم اول کدام نگرانی را روشن کنیم.","برای نشان‌دادن احترام، ابتدا سابقه همکاری شرکت را مرور می‌کنم."],"correct":1,"reasons":["بررسی پرونده لازم است، اما قبل از شنیدن اولویت مهمان ممکن است وقت او صرف موضوع کم‌اهمیت‌تری شود.","هم احترام و وقت مهمان دیده می‌شود، هم خودش موضوع مهم گفت‌وگو را مشخص می‌کند.","یادآوری همکاری گذشته مؤدبانه است، اما در شروعِ این ملاقات به ناراحتی و محدودیت زمانی او پاسخ نمی‌دهد."],"ask":"پاسخ انتخابی‌تان را با لحن جدی و صمیمی بگویید."},{"q":"مشتری می‌گوید چند بار پیگیری کرده و جوابی نگرفته است. چه پاسخ می‌دهید؟","options":["«حق با شماست؛ حتماً شعبه مقصر بوده و جبران می‌کنیم.»","«ابتدا با صدور صحبت کنیم؛ بعد درباره ناراحتی‌تان حرف می‌زنیم.»","«می‌فهمم بی‌خبری ناراحت‌کننده بوده؛ بیایید وضعیت پرونده را روشن کنیم.»"],"correct":2,"reasons":["همدلی لازم است، اما مقصرشناسی و قول جبران قبل از بررسی، تعهد بی‌پشتوانه ایجاد می‌کند.","پیگیری فنی خوب است، اما کنارگذاشتن ناراحتی مشتری در ابتدای ملاقات، احساس شنیده‌نشدن می‌دهد.","ناراحتی را به رسمیت می‌شناسید و بی‌آنکه نتیجه‌ای حدس بزنید، گفت‌وگو را به اقدام مشخص می‌برید."],"ask":"این جمله را بدون عذرخواهی تکراری و با مکث مناسب بگویید."},{"q":"وقتی مدیرعامل از تأخیر صحبت می‌کند، کدام رفتار غیرکلامی مناسب‌تر است؟","options":["رو به او می‌نشینم، نگاه طبیعی دارم و در صورت نیاز نکته کوتاه یادداشت می‌کنم.","برای نشان‌دادن صمیمیت، در بیشتر صحبت‌ها لبخند می‌زنم.","بیشتر به پرونده نگاه می‌کنم تا بداند مشغول حل مشکل هستم."],"correct":0,"reasons":["نگاه و توجه متناسب، شنیدن را نشان می‌دهد؛ یادداشت کوتاه هم بدون قطع ارتباط می‌تواند مفید باشد.","لبخند مداوم هنگام شنیدن شکایت، ممکن است با جدیت مسئله هماهنگ نباشد و بی‌توجهی برداشت شود.","تمرکز طولانی بر پرونده، گرچه به قصد رسیدگی است، فرصت شنیدن مستقیم نگرانی مهمان را کم می‌کند."],"ask":"دو حالت چهره و بدن را اجرا کنید؛ کدام برای مشتری ناراضی مناسب‌تر است؟"}],"2":[{"q":"مدیر منطقه در حضور مشتری‌ها درباره صف طولانی سؤال می‌کند. چه می‌گویید؟","options":["«احتمالاً سامانه کند شده؛ همکارها دارند رسیدگی می‌کنند.»","«صف طولانی شده؛ الان انتظار را مدیریت می‌کنیم و دلیلش را هم بررسی می‌کنم.»","«اجازه بدهید آمار روزهای قبل را بیاورم تا علت روشن شود.»"],"correct":1,"reasons":["ممکن است سامانه مشکل داشته باشد، اما بدون بررسی علت را حدس می‌زنید و اقدام فوری را روشن نمی‌کنید.","مشکل را می‌پذیرید، کار فوری را می‌گویید و علت را بدون سرزنش یا حدس پیگیری می‌کنید.","آمار قبلی برای بررسی مفید است، اما در برابر صف فعلی، پاسخ اول باید شامل اقدام همین لحظه باشد."],"ask":"پاسخ را در بیست ثانیه و با صدای محکم و آرام اجرا کنید."},{"q":"هنوز دلیل تأخیر را نمی‌دانید. پاسخ حرفه‌ای شما چیست؟","options":["«طبق تجربه، احتمالاً فشار مراجعه‌ها علت اصلی است.»","«از مسئول صدور می‌خواهم همین‌جا علت را توضیح بدهد.»","«هنوز دلیل دقیق روشن نیست؛ بررسی می‌کنم و تا ساعت مشخص خبر می‌دهم.»"],"correct":2,"reasons":["تجربه می‌تواند سرنخ باشد، اما احتمال را نباید به‌جای علت تأییدشده به مدیر اعلام کرد.","کمک‌گرفتن از مسئول صدور خوب است، اما توضیح‌خواستن جلوی جمع ممکن است او را بی‌دلیل در موضع دفاع قرار دهد.","اطلاعات نامعلوم را صادقانه جدا می‌کنید و با موعد واقعی، مسئولیت پاسخ بعدی را می‌پذیرید."],"ask":"یک موعد واقع‌بینانه انتخاب کنید و جمله را بگویید."},{"q":"همکار شما اطلاعات نادرستی درباره صف می‌گوید. چه واکنشی دارید؟","options":["«اجازه بدهید یک نکته را دقیق‌تر بگویم...»؛ بعداً جدا با همکار صحبت می‌کنم.","صبر می‌کنم بازدید تمام شود و بعد اطلاعات را اصلاح می‌کنم.","همان‌جا از همکار می‌خواهم توضیحش را پس بگیرد."],"correct":0,"reasons":["در همان لحظه اطلاعات درست ارائه می‌شود و همکار هم در حضور دیگران سرزنش نمی‌شود.","تا پایان بازدید، مدیر منطقه ممکن است بر اساس اطلاعات نادرست تصمیم یا قضاوت کند.","اصلاح فوری مهم است، اما وادارکردن همکار به عقب‌نشینی جلوی جمع، شأن او را بی‌دلیل خدشه‌دار می‌کند."],"ask":"فقط با یک جمله، اشتباه را بدون نام‌بردن از مقصر اصلاح کنید."}],"3":[{"q":"در شروع جلسه، خانم احمدی را چطور به مدیرعامل معرفی می‌کنید؟","options":["«خانم احمدی از همکاران باتجربه ما هستند.»","«خانم احمدی مسئول بررسی بیمه‌های مهندسی هستند و بخش فنی را توضیح می‌دهند.»","«خانم احمدی هم در صورت نیاز می‌توانند چند نکته تکمیلی بگویند.»"],"correct":1,"reasons":["تعریف از تجربه خوب است، اما مهمان هنوز نمی‌داند ایشان برای چه موضوعی مسئول پاسخ‌اند.","نام، مسئولیت و نقش گفت‌وگو روشن می‌شود و کارشناس از ابتدا جایگاه حرفه‌ای خود را دارد.","عبارت «در صورت نیاز» نقش کارشناس را فرعی نشان می‌دهد؛ در حالی که موضوع اصلی این بخش تخصص اوست."],"ask":"کارشناس واقعی شعبه خودتان را با نام و نقش معرفی کنید."},{"q":"پیش از معرفی یکی از مهمان‌ها، عنوان شغلی او را دقیق نمی‌دانید. چه می‌کنید؟","options":["برای احترام، عنوان بالاتری به کار می‌برم تا مطمئن باشم ناراحت نمی‌شود.","فقط نام او را می‌گویم و مسئولیتش را مطرح نمی‌کنم.","در زمان مناسب کوتاه می‌پرسم عنوان و نقش درست ایشان چیست."],"correct":2,"reasons":["عنوان بالاتر هم ممکن است اشتباه باشد و برای مهمان یا سایر افراد سوءتفاهم ایجاد کند.","نام‌بردن محترمانه است، ولی وقتی نقش فرد در جلسه مهم است، حذف آن معرفی را ناقص می‌کند.","به‌جای حدس‌زدن، اطلاعات را محترمانه از خود فرد می‌گیرید و معرفی دقیقی انجام می‌دهید."],"ask":"یک جمله مؤدبانه برای پرسیدن عنوان مهمان بگویید."},{"q":"مهمان سؤال فنی را از مدیر منطقه می‌پرسد. بهترین واکنش شما چیست؟","options":["از مدیر منطقه می‌خواهم توضیح را شروع کند و کارشناس بعداً تکمیل کند.","می‌گویم سؤال را یادداشت کنند تا کارشناس پس از جلسه جواب بدهد.","با احترام به مدیر منطقه، از خانم احمدی می‌خواهم پاسخ فنی را همین‌جا توضیح بدهد."],"correct":2,"reasons":["این روش ظاهراً محترمانه است، اما پاسخ تخصصی را ابتدا از کسی می‌خواهد که لزوماً مسئول جزئیات فنی نیست.","ثبت سؤال منظم است، اما وقتی کارشناس در جلسه حضور دارد، عقب‌انداختن پاسخ دلیل روشنی ندارد.","جایگاه مدیر منطقه حفظ می‌شود و مهمان پاسخ را مستقیماً از فرد آگاه و مسئول دریافت می‌کند."],"ask":"بدون قطع محترمانه‌نبودن صحبت، نوبت پاسخ را به خانم احمدی بدهید."}],"4":[{"q":"مهمان پنج دقیقه زود آمده و اتاق جلسه آماده نیست. چه می‌گویید؟","options":["«خوش آمدید؛ اگر موافقید گزارش آغاز بازدید را در اتاق آرام کنار سالن شروع کنیم.»","«بسیار خوش آمدید؛ چند دقیقه در پذیرش تشریف داشته باشید تا اتاق آماده شود.»","«با مسئول هماهنگی تماس می‌گیرم تا همین الان برنامه را تنظیم کند.»"],"correct":0,"reasons":["هم استقبال می‌کنید و هم راه جایگزین عملی می‌دهید تا زمان محدود مهمان هدر نرود.","استقبال مؤدبانه است، ولی بدون پیشنهاد جایگزین، مهمان همچنان منتظر آماده‌شدن اتاق می‌ماند.","تماس برای هماهنگی لازم است، اما به مهمان نمی‌گویید در این فاصله چگونه می‌توانید شروع کنید."],"ask":"خوشامدگویی را همراه با راه‌حل و لحن آرام اجرا کنید."},{"q":"مهمان می‌خواهد یک پرونده واقعی خسارت را ببیند. چه می‌گویید؟","options":["نام و شماره بیمه‌گذار را می‌پوشانم و پرونده واقعی را نشان می‌دهم.","می‌گویم اطلاعات پرونده محرمانه است و نمونه مجازِ بدون اطلاعات شخصی را نشان می‌دهم.","می‌گویم این بخش از بازدید را حذف کنیم و سراغ بخش بعدی برویم."],"correct":1,"reasons":["پوشاندن نام و شماره لزوماً اجازه نمایش سایر اطلاعات محرمانه را ایجاد نمی‌کند؛ مجوز و ضابطه لازم است.","محدودیت را محترمانه می‌گویید و با نمونه مجاز، هدف آموزشی بازدید را هم حفظ می‌کنید.","حذف کامل بخش فنی شاید ساده باشد، ولی پیش از آن می‌توان نمونه مجاز جایگزین پیشنهاد داد."],"ask":"در یک جمله، درخواست را محترمانه رد و جایگزین پیشنهاد کنید."},{"q":"بازدید تمام شده و دو موضوع نیازمند پیگیری‌اند. بدرقه را چطور انجام می‌دهید؟","options":["از مهمان تشکر می‌کنم و می‌گویم «به‌زودی نتیجه را اطلاع می‌دهیم».","درباره مهم‌ترین بخش بازدید نظرش را می‌پرسم و همان‌جا خداحافظی می‌کنم.","تشکر می‌کنم و برای هر موضوع، مسئول پیگیری و موعد اعلام وضعیت را کوتاه می‌گویم."],"correct":2,"reasons":["تشکر مناسب است، اما «به‌زودی» برای مسئول و زمان پیگیری معنای روشنی ندارد.","نظرخواهی مفید است، اما دو موضوع باز جلسه همچنان بدون مسئول و موعد باقی می‌مانند.","هم مهمان محترمانه بدرقه می‌شود، هم نتیجه بازدید قابل پیگیری و روشن است."],"ask":"بدرقه را در دو جمله کوتاه اجرا کنید."}],"5":[{"q":"در جلسه، مدیر منابع انسانی وسط صحبت کارشناس می‌پرد. چه می‌گویید؟","options":["«سؤالتان مهم است؛ اجازه بدهید توضیح همکارم کامل شود، بعد مستقیم به همان سؤال می‌رسیم.»","«پیشنهاد می‌کنم ابتدا همه سؤال‌های شما را بشنویم و بعد گزارش را ارائه کنیم.»","«از کارشناس می‌خواهم همین‌جا توضیحش را متوقف کند تا سؤال را جواب بدهیم.»"],"correct":0,"reasons":["نگرانی مهمان پذیرفته می‌شود، اما نوبت صحبت همکار و مسیر جلسه هم حفظ می‌ماند.","شنیدن سؤال‌ها مفید است، ولی تغییر ناگهانی ترتیب جلسه ممکن است زمان و گفت‌وگوی تخصصی را از مسیر خارج کند.","پاسخ به سؤال مهم است، اما قطع‌کردن کامل صحبت کارشناس، الگوی نوبت‌دهی منصفانه‌ای ایجاد نمی‌کند."],"ask":"همان جمله را محترمانه و با کف دست باز اجرا کنید."},{"q":"آخر جلسه، مدیر مالی سؤال تازه‌ای مطرح می‌کند و وقت کم است. چه می‌کنید؟","options":["یک پاسخ کلی می‌دهم تا مهمان بی‌جواب نماند.","سؤال را ثبت می‌کنم، مسئول پاسخ و زمانی برای برگشت به آن می‌گویم.","دستور جلسه را کنار می‌گذارم تا همان سؤال به‌طور کامل بررسی شود."],"correct":1,"reasons":["پاسخ کلی شاید سریع باشد، اما ممکن است نادقیق باشد و مسئولیت پیگیری را مشخص نمی‌کند.","سؤال دیده می‌شود و با مسئول و موعد روشن، بدون برهم‌زدن جمع‌بندی جلسه پیگیری می‌شود.","بررسی کامل ارزش دارد، ولی بدون توافق درباره تغییر زمان، ممکن است جلسه بدون تصمیم اصلی تمام شود."],"ask":"با یک جمله سؤال را ثبت کنید و گفت‌وگو را برگردانید."},{"q":"جلسه درباره پوشش‌ها تمام شده، اما یک درخواست هنوز بررسی نشده است. چه جمع‌بندی می‌کنید؟","options":["موضوع‌های قطعی را نام می‌برم و برای موضوع باز، مسئول و زمان خبر بعدی را مشخص می‌کنم.","نکات اصلی جلسه را مرور می‌کنم و می‌گویم جزئیات بعداً مکتوب می‌شود.","به مهمان می‌گویم کار خوب پیش رفت و در تماس بعدی نتیجه را می‌گوییم."],"correct":0,"reasons":["تفاوت تصمیم قطعی و موضوع باز روشن می‌شود و هر اقدام یک مسئول و موعد پیگیری دارد.","مرور نکات خوب است، اما اگر موضوع باز و زمان پیگیری معلوم نباشد، جلسه همچنان مبهم تمام می‌شود.","لحن مثبت مناسب است، اما بدون ذکر تصمیم‌ها و زمان مشخص، از آن نمی‌توان برنامه عمل ساخت."],"ask":"جمع‌بندی جلسه را در سی ثانیه با لحن مطمئن بیان کنید."}]};
