window.ALBORZ_SPRINT_QA_PART_B={"6":[{"q":"بیمه‌گذار نگران، یک سؤال را دوباره می‌پرسد. چطور پاسخ می‌دهید؟","options":["همان توضیح را آرام‌تر و شمرده‌تر تکرار می‌کنم.","می‌پرسم کدام بخش نامشخص بوده، بعد قدم اول را کوتاه توضیح می‌دهم.","می‌گذارم همه نگرانی‌هایش را بگوید و بعد تمام مراحل را یک‌جا شرح می‌دهم."],"correct":1,"reasons":["آرام‌گفتن خوب است، اما ممکن است مشکل اصلی مشتری در واژه‌ها یا ترتیب توضیح باشد؛ صرف تکرار کافی نباشد.","ابتدا ابهام را مشخص می‌کنید و سپس با یک قدم قابل انجام، فشار ذهنی مشتری را کمتر می‌کنید.","شنیدن نگرانی ضروری است، ولی ارائه تمام مراحل به‌صورت یک‌جا ممکن است فرد مضطرب را بیشتر گیج کند."],"ask":"این پاسخ را با مکث و سرعت آرام اجرا کنید."},{"q":"مشتری در تماس تصویری نگاهش به دوربین نیست. بهترین واکنش چیست؟","options":["می‌پرسم آیا توضیح روشن است و لازم است بخشی را دوباره بگویم.","فرض می‌کنم به دلیل استرس حواسش پرت شده و سرعت توضیح را بالا می‌برم.","از او می‌خواهم هنگام صحبت مستقیم به دوربین نگاه کند تا مطمئن شوم گوش می‌دهد."],"correct":0,"reasons":["به‌جای تفسیر نگاه، با یک سؤال ساده فهم مطلب را بررسی می‌کنید و حق انتخاب برای شنیدن دوباره می‌دهید.","استرس ممکن است وجود داشته باشد، اما از جهت نگاه نمی‌توان علت را فهمید؛ تندتر حرف‌زدن هم لزوماً کمک نمی‌کند.","نگاه به دوربین شرط گوش‌دادن نیست؛ این درخواست می‌تواند به‌جای روشن‌شدن موضوع، به مخاطب فشار وارد کند."],"ask":"بدون قضاوت درباره نگاه، یک سؤال روشن‌کننده بپرسید."},{"q":"مشتری می‌پرسد: «پس خسارتم حتماً پرداخت می‌شود؟» چه می‌گویید؟","options":["«اگر مدارک کامل باشد، احتمال پرداخت خیلی زیاد است.»","«باید بررسی شود؛ لطفاً منتظر نظر واحد فنی بمانید.»","«نتیجه به بررسی پوشش و مدارک بستگی دارد؛ الان قدم بعدی را با هم روشن کنیم.»"],"correct":2,"reasons":["کامل‌بودن مدارک به‌تنهایی نتیجه پرداخت را تعیین نمی‌کند؛ این جمله ممکن است انتظار نادرست بسازد.","این پاسخ از قول قطعی دور است، اما مشتری را بدون توضیح قدم بعدی و مسیر پیگیری رها می‌کند.","صادقانه محدوده پاسخ را می‌گویید و با راهنمایی کوتاه، احساس بلاتکلیفی را کمتر می‌کنید."],"ask":"با لحن همدلانه و بدون وعده قطعی پاسخ دهید."}],"7":[{"q":"مدیر خرید می‌خواهد برای خسارتِ در حال بررسی استثنا قائل شوید. چه می‌گویید؟","options":["«درخواستتان را برای مدیر بالاتر می‌فرستم؛ امیدوارم استثنا بدهند.»","«به سابقه همکاری احترام می‌گذارم، اما نتیجه باید از مسیر بررسی رسمی مشخص شود.»","«برای مشتری قدیمی تمام تلاشمان را می‌کنیم؛ فعلاً نگران نتیجه نباشید.»"],"correct":1,"reasons":["ارجاع ممکن است لازم شود، اما صحبت از «استثنا» پیش از روشن‌شدن ضابطه، انتظار تصمیم خارج از روال ایجاد می‌کند.","هم احترام به مشتری حفظ می‌شود و هم مرز اختیار و فرآیند رسیدگی بدون مقابله روشن می‌ماند.","عبارت اطمینان‌بخشِ مبهم ممکن است از نظر مشتری نشانه قول نتیجه ویژه یا پرداخت باشد."],"ask":"همین «نه» را با لحن محکم و بدون حالت دفاعی بگویید."},{"q":"پرونده هنوز نتیجه فنی ندارد. مشتری می‌پرسد چه زمانی پرداخت می‌شود. پاسخ چیست؟","options":["«اگر مثل پرونده‌های مشابه باشد، احتمالاً این هفته تعیین تکلیف می‌شود.»","«تا نظر فنی نیاید، هیچ خبری نمی‌توانم به شما بدهم.»","«زمان نتیجه قطعی نیست؛ تا موعد مشخص، وضعیت بررسی و مدارک را خبر می‌دهم.»"],"correct":2,"reasons":["شباهت با پرونده‌های قبلی جای بررسی این پرونده را نمی‌گیرد؛ احتمال را نباید به موعد قطعی تبدیل کرد.","نتیجه نهایی هنوز معلوم نیست، ولی درباره مرحله پرونده و کار بعدی می‌توان اطلاع‌رسانی کرد.","تفاوت زمان اعلام وضعیت و زمان تصمیم نهایی روشن می‌شود و یک قول قابل انجام می‌دهید."],"ask":"یک موعد واقعی برای اعلام وضعیت بگویید، نه برای پرداخت."},{"q":"مشتری ناراضی از انتقال قراردادهای بعدی حرف می‌زند. کدام پاسخ بهتر است؟","options":["«کدام بخش پاسخ‌گویی بیشترین مشکل را برای شما ایجاد کرده؟ برای همان مورد راه پیگیری می‌گذاریم.»","«اجازه بدهید اول تخفیف تمدید را بررسی کنیم تا نگرانی‌تان کمتر شود.»","«بهتر است مدیرعامل شما با مدیریت منطقه تماس بگیرد تا موضوع سریع‌تر حل شود.»"],"correct":0,"reasons":["از فشار و تهدید وارد دعوا نمی‌شوید؛ علت اصلی نارضایتی را می‌فهمید و وارد اقدام مشخص می‌شوید.","تخفیف ممکن است ربطی به مشکل اصلیِ پاسخ‌گویی نداشته باشد و بدون اختیار هم نباید وعده داده شود.","ارجاع فوری ممکن است لازم نباشد و به‌جای مسئولیت‌پذیری شعبه، احساس پاس‌دادن مشکل ایجاد کند."],"ask":"این سؤال را با کنجکاوی حرفه‌ای، نه لحن دفاعی، بپرسید."}],"8":[{"q":"هنگام بازدید ستادی، مشتری با صدای بلند از انتظار طولانی اعتراض می‌کند. اولین واکنش چیست؟","options":["از او می‌خواهم آرام‌تر صحبت کند تا بتوانیم به موضوع رسیدگی کنیم.","پیشنهاد می‌کنم به اتاق کناری برویم تا نظم سالن حفظ شود.","با صدای آرام می‌پرسم چه اتفاقی افتاده و آیا نیاز فوری دارد."],"correct":2,"reasons":["آرام‌ترشدن فضا مهم است، اما اگر پیش از شنیدن مشکل از مشتری بخواهید صدایش را پایین بیاورد، ممکن است احساس طردشدن کند.","پیشنهاد اتاق دیگر می‌تواند خوب باشد، اما وقتی پیش از شنیدن نگرانی مطرح شود، ممکن است تلاش برای پنهان‌کردن اعتراض برداشت شود.","ابتدا با احترام و آرامش، موضوع و فوریت را می‌فهمید و بعد مسیر رسیدگی یا فضای آرام‌تر پیشنهاد می‌کنید."],"ask":"اولین جمله را با صدای پایین و چهره جدی اما آرام اجرا کنید."},{"q":"سامانه نوبت‌دهی قطع شده و صف در حال زیادشدن است. چه می‌گویید؟","options":["به مراجعه‌کنندگان می‌گویم اختلال پیش آمده، مسیر جایگزینِ مجاز چیست و چه کسی پیگیری می‌کند.","توضیح می‌دهم تیم فنی مشغول کار است و از همه می‌خواهم کمی صبر کنند.","پیشنهاد می‌کنم پرونده‌های غیرضروری در روز دیگری مراجعه کنند تا ازدحام کمتر شود."],"correct":0,"reasons":["هم واقعیت را می‌گویید و هم مردم می‌دانند اکنون چگونه نوبت یا درخواست خود را دنبال کنند.","اطلاع‌رسانی خوب است، ولی بدون مسیر جایگزین یا زمان به‌روزرسانی، مردم همچنان بلاتکلیف می‌مانند.","تغییر زمان مراجعه بدون بررسی فوریت و ضابطه، ممکن است حق خدمت‌گیری افراد را بی‌دلیل عقب بیندازد."],"ask":"این اطلاع‌رسانی را مثل یک اعلام کوتاه در سالن بیان کنید."},{"q":"همراه مدیر ستادی می‌گوید: «مشتری معترض را از جلوی چشم مهمان ببرید.» واکنش چیست؟","options":["می‌گویم ابتدا بازدید را تمام کنیم و سپس به شکایت رسیدگی شود.","می‌گویم اگر مشتری مایل باشد، در فضای آرام‌تر رسیدگی می‌کنیم و فعلاً مشکلش را می‌شنویم.","از مشتری می‌خواهم برای نظم سالن به اتاق دیگری برود و همان‌جا منتظر بماند."],"correct":1,"reasons":["عقب‌انداختن شکایت فقط به خاطر بازدید، اولویت خدمت‌رسانی و احترام به مشتری را نادیده می‌گیرد.","فضای آرام‌تر با رضایت مشتری پیشنهاد می‌شود و رسیدگی به اعتراض هم فدای ظاهر بازدید نمی‌شود.","جابه‌جایی به‌عنوان دستور و بدون شنیدن نیاز مشتری، ممکن است احساس کنارگذاشته‌شدن به او بدهد."],"ask":"پاسخ خود به همراه مدیر و سپس پیشنهاد به مشتری را اجرا کنید."}],"9":[{"q":"نماینده پاسخ سریع می‌خواهد، مدیر مالی گزارش مکتوب و کارشناس مدارک کامل. چه می‌کنید؟","options":["اول مشکل مدیر مالی را حل می‌کنم، چون تصمیم مالی با اوست.","یک پاسخ مشترک می‌دهم تا بعداً هر کس جزئیات را جدا پیگیری کند.","از هر نفر یک نیاز مشخص می‌پرسم و مسیر و مسئول پیگیری را جمع‌بندی می‌کنم."],"correct":2,"reasons":["مدیر مالی مهم است، اما نیاز نماینده و مانع فنیِ کارشناس هم در نتیجه پرونده اثر دارد.","پاسخ کلی ممکن است جلسه را کوتاه کند، ولی اختلاف انتظارها و مسئول هر کار را روشن نمی‌کند.","با شنیدن هر سه نقش، می‌توانید اطلاعات لازم، کانال پاسخ و اقدام هر نفر را دقیق مشخص کنید."],"ask":"برای هر سه نفر یک سؤال کوتاه طرح کنید."},{"q":"نماینده می‌خواهد وضعیت پرونده را در پیام‌رسان شخصی دریافت کند. چه می‌گویید؟","options":["از مسیر رسمی، اطلاعات مجاز را می‌فرستم و برای هماهنگی سریع از راه مورد تأیید خبر می‌دهم.","برای سرعت، فقط عکس صفحه بدون نام بیمه‌گذار را در پیام‌رسان می‌فرستم.","به او می‌گویم اطلاعات محرمانه است و خودش از شرکت مشتری پیگیری کند."],"correct":0,"reasons":["هم سرعت پیگیری در نظر گرفته می‌شود و هم اطلاعات فقط از کانال و به گیرنده مجاز می‌رسد.","برداشتن نام، به‌تنهایی مجوز ارسال تصویر پرونده از کانال شخصی نیست؛ داده‌های دیگر هم می‌توانند حساس باشند.","حفظ محرمانگی درست است، اما قطع کامل هماهنگی بدون جایگزین رسمی، همکاری را بی‌دلیل دشوار می‌کند."],"ask":"در دو جمله، محدودیت را توضیح بدهید و راه جایگزین بگویید."},{"q":"نماینده می‌خواهد پرونده مشتری خودش زودتر رسیدگی شود. چه پاسخ می‌دهید؟","options":["می‌گویم چون مشتری قدیمی است، نوبتش را با چند پرونده جابه‌جا می‌کنیم.","فوریت را با معیارهای مصوب می‌سنجم و زمان اعلام وضعیت را روشن می‌کنم.","می‌گویم همه پرونده‌ها فقط بر اساس زمان ثبت بررسی می‌شوند و استثنا نداریم."],"correct":1,"reasons":["وفاداری مشتری ارزشمند است، اما تغییر نوبت بدون معیار معتبر ممکن است حق مشتریان دیگر را نادیده بگیرد.","تصمیم درباره اولویت به معیار روشن تکیه دارد و نماینده هم می‌داند چه زمانی خبر بعدی را می‌گیرد.","رعایت نوبت مهم است، ولی ممکن است ضوابط برای شرایط واقعاً فوری مسیر متفاوتی پیش‌بینی کرده باشند."],"ask":"با لحن دوستانه ولی قاطع، معیار اولویت را توضیح دهید."}],"10":[{"q":"مهمان در پایان جلسه می‌گوید: «پس همه چیز قطعی شد؟» درحالی‌که دو موضوع باز است. چه می‌گویید؟","options":["«جلسه خوبی داشتیم؛ جمع‌بندی کامل را امروز برایتان می‌فرستیم.»","«یک مورد قطعی شد؛ دو مورد هنوز بررسی می‌شود. اجازه بدهید کوتاه نام ببرم.»","«بله، از نظر پیگیری همه چیز روشن شده؛ فقط منتظر تأیید فنی هستیم.»"],"correct":1,"reasons":["فرستادن جمع‌بندی مفید است، اما سوءتفاهم مهمان درباره قطعی‌بودن همه موضوع‌ها باید همین‌جا اصلاح شود.","تفاوت توافق نهایی و موضوع باز را محترمانه و فوری روشن می‌کنید، بدون طولانی‌کردن خداحافظی.","عبارت «همه چیز روشن شده» ممکن است با «همه چیز تأیید شده» اشتباه گرفته شود و انتظار نادرست ایجاد کند."],"ask":"در سه جمله کوتاه این برداشت را اصلاح کنید."},{"q":"برای پیگیری سه موضوع جلسه چه جمع‌بندی‌ای بهتر است؟","options":["نام بخش مسئول هر کار و یک زمان کلی برای اطلاع‌رسانی را اعلام می‌کنم.","می‌گویم همکارها صورت‌جلسه را تکمیل می‌کنند و بعد برنامه پیگیری می‌فرستیم.","برای هر کار، فرد یا واحد مسئول و موعد اعلام وضعیت مشخص می‌کنم."],"correct":2,"reasons":["نام بخش و زمان کلی شروع خوبی است، ولی وقتی چند اقدام مختلف داریم، ممکن است مسئولیت هر مورد همچنان مبهم بماند.","صورت‌جلسه لازم است، اما اگر در پایان جلسه مسئول و موعد معلوم نشود، احتمال برداشت متفاوت بالا می‌رود.","مهمان برای هر موضوع می‌داند چه کسی پیگیر است و در چه زمانی چه خبری دریافت می‌کند."],"ask":"مسئول و زمان دو اقدام متفاوت را پشت سر هم نام ببرید."},{"q":"تاریخ نتیجه بررسی فنی هنوز روشن نیست. چه وعده‌ای درست است؟","options":["«تا پایان هفته جواب قطعی می‌گیریم»؛ تا مشتری با خیال راحت برود.","«وقتی نتیجه رسید، خبر می‌دهیم»؛ تا قولی درباره زمان نداده باشیم.","«نتیجه قطعی معلوم نیست، اما در تاریخ مشخص وضعیت بررسی را اطلاع می‌دهیم.»"],"correct":2,"reasons":["اگر موعد نتیجه در اختیار شما نیست، قول تاریخ قطعی ممکن است قابل انجام نباشد و اعتماد را کم کند.","قول ندادن درباره نتیجه درست است، اما نداشتن زمانِ حتی برای گزارش وضعیت، مشتری را بلاتکلیف می‌گذارد.","از نتیجه نامعلوم وعده نمی‌دهید؛ برای کار قابل کنترل یعنی اطلاع از وضعیت بعدی موعد مشخص می‌گذارید."],"ask":"با لحن مطمئن، تفاوت «موعد پیگیری» و «موعد نتیجه قطعی» را بگویید."}]};
;


/* session2-sprint12-feedback.js */
/* Sprint 1–2 assessment data + shared renderer, reused in all ten techniques.
   Requires batch files and previous educational enrichments; must run before first-practice-polish and extended renderer. */
(function(){
"use strict";
const combined=Object.assign({},window.ALBORZ_SPRINT_QA_PART_A||{},window.ALBORZ_SPRINT_QA_PART_B||{});
const bank=window.ALBORZ_TECH_DATA||{};
for(let t=1;t<=10;t++){
 const set=combined[t];
 if(!Array.isArray(set)||set.length!==3)throw Error("Missing 3 questions for technique "+t);
 const mapped=set.map((z,i)=>{
  if(!z.q||!Array.isArray(z.options)||z.options.length!==3||!Number.isInteger(z.correct)||z.correct<0||z.correct>2||
     !Array.isArray(z.reasons)||z.reasons.length!==3||new Set(z.reasons).size!==3||
     z.options.some(v=>String(v).length<12)||z.reasons.some(v=>String(v).length<25))
    throw Error("Incomplete question or rationale for technique "+t+" question "+(i+1));
  return {q:z.q,options:z.options.slice(),correct:z.correct,optionReasons:z.reasons.slice(),why:z.reasons[z.correct],ask:z.ask};
 });
 if(t===1){
   Q.splice(0,Q.length,...mapped.map(z=>({q:z.q,opts:z.options,right:z.correct,optionReasons:z.optionReasons,
       ex:z.why,follow:z.ask})));
 }else{
   if(!bank[t])throw Error("Missing technique "+t);
   bank[t].quiz=mapped;
 }
}
function render(items,answers,action,e,first=false){
 const current=answers||{};
 return items.map((q,i)=>{
   const opt=first?q.opts:q.options,correct=first?q.right:q.correct;
   const reasons=q.optionReasons||[];
   const answer=current[i],selected=Number.isInteger(answer)&&answer>=0&&answer<3;
   const head='<div class="lab-quiz-question" role="group" aria-label="پرسش '+(i+1)+'"><h3>پرسش '+(i+1)+'</h3><p class="lead">'+e(q.q)+'</p>';
   const choices=opt.map((o,k)=>{
     const isThis=selected&&answer===k, correctChoice=k===correct;
     const css=isThis?(correctChoice?' selected selected-correct':' selected selected-incorrect'):'';
     return '<button type="button" class="answer lab-choice'+css+'" aria-pressed="'+isThis+
       '" data-quiz-index="'+i+'" data-option-index="'+k+'" onclick="'+action(i,k)+'">'+
       '<span class="lab-answer-index">'+(k+1)+'</span><span class="lab-answer-label">'+e(o)+'</span>'+
       (isThis?'<span class="lab-answer-mark" aria-hidden="true">'+(correctChoice?'✓':'×')+'</span>':'')+
       '</button>';
   }).join('');
   let feedback='';
   if(selected){
     const yes=answer===correct;
     const primary='<div class="lab-feedback-selected '+(yes?'correct':'incorrect')+'"><strong>'+
       (yes?'✅ انتخاب شما درست است.':'✖ این انتخاب بهترین پاسخ نیست.')+'</strong>'+
       '<p>'+e(reasons[answer])+'</p></div>';
     const others=opt.map((v,k)=>{
       if(k===answer)return '';
       const isRight=k===correct;
       return '<div class="lab-feedback-another '+(isRight?'right':'wrong')+'"><b>'+
          (isRight?'✓ گزینه '+(k+1)+' — پاسخ مناسب':'✕ گزینه '+(k+1)+' — چرا مناسب نیست؟')+
          '</b><p>'+e(reasons[k])+'</p></div>';
     }).join('');
     feedback='<div class="lab-feedback-result" role="status" aria-live="polite" aria-label="تحلیل پاسخ">'+primary+
       '<div class="lab-feedback-subtitle">بررسی دو گزینه دیگر</div><div class="lab-feedback-others">'+others+'</div>'+
       '<details class="accordion lab-feedback-practice"><summary>تمرین کوتاه</summary><div>'+
        e(first?q.follow:q.ask)+'</div></details></div>';
   }
   return '<section class="poll lab-poll lab-quiz-question-wrap">'+head+choices+feedback+'</div></section>';
 }).join('');
}
window.ALBORZ_QUIZ_UI={render,release:"sprint12-r1",totalQuestions:30};
window.ALBORZ_ASSESSMENT_READY=true;
})();
;
